INSERT INTO grammar_lessons (id, grammar_chapter_id, title, pattern, meaning_vi, explanation, formation, jlpt_level_id, display_order, is_published, version) VALUES
(452, 90, 'Bài 1.1 - ～が早いか', '～が早いか', 'Vừa mới … thì đã', 'Diễn tả văn cảnh khi vừa mới diễn ra thì đã lập tức , nhanh chóng , bất ngờ chuyển sang hành động 2. Chú ý : Đi cùng với những động từ mnag tính khoảnh khắc nhanh , vế sau thể hiện ít nhiều sự bất ngờ ngoài dự tính của người nói. Không đi kèm với những câu thể hiện ý chí, nguyện vọng hay kêu gọi đối phương thực hiện hành động.', '～が早いか', 5, 1, TRUE, 1),
(453, 90, 'Bài 1.2 - ～や / ～や否や', '～や / ～や否や', 'Vừa mới ... xong thì …', 'Diễn tả một hành động xảy ra gần như đồng thời với hành động trước đó (vừa mới xong thì …). Chú ý : Mẫu câu này dùng với những động từ diễn tả hành động xảy ra trong khoảnh khắc, theo sau đó là vế câu miêu tả sự việc, hiện thực, không diễn tả quan điểm, nguyện vọng, hay suy nghĩ của người nói.', '～や / ～や否や', 5, 2, TRUE, 1),
(454, 90, 'Bài 1.3 - ～なり', '～なり', 'Vừa mới ... thì đã…', 'Một hành động vừa mới xảy ra thì liền ngay sau đó một hành động khác cũng xảy ra. Chú ý : Hành động sau thường là ngoài dự đoán của người nói. Chủ ngữ của câu thường là ngôi thứ ba. Hành động trước và sau đều có cùng một chủ thể hành động (chủ ngữ là một người)', '～なり', 5, 3, TRUE, 1),
(455, 90, 'Bài 1.4 - ～そばから', '～そばから', 'Dù có làm A nhưng B vẫn xảy ra', 'Hành động gì đó vừa mới xảy ra thì ngay lập tức một hành động đối nghịch lại với hành động đó cũng xảy ra, và điều này lặp đi lặp lại nhiều lần. Chú ý : Mẫu câu này thường dùng với ý nghĩa không tốt.', '～そばから', 5, 4, TRUE, 1),
(456, 90, 'Bài 1.5 - ～てからというもの（は）', '～てからというもの（は）', 'Sau khi A thì B xảy ra ( liên tục xảy ra)', 'Diễn tả 1 văn cảnh kể từ khi hành động nào đó xảy ra, thì có một sự thay đổi và sự thay đổi này cứ giữ nguyên mãi về sau. Chú ý : Mẫu câu này không dùng với những mốc quá khứ gần. Vế sau diễn tả tình trạng sau khi thay đổi.', '～てからというもの（は）', 5, 5, TRUE, 1),
(457, 90, 'Bài 1.6 - ～にあって', '～にあって', 'Chính vì', 'Chính vì hoàn cảnh/điều kiện đặc biệt như vậy nên sự việc/hành động gì đó mới xảy ra Chú ý : Đi kèm với N chỉ trạng thái , thời kỳ , địa điểm...Trong trường hợp điều xảy ra trái ngược với trạng thái ban đầu thì sử dụng mẫu にあっても dịch với nghĩa là ‘’ cho dù ‘’', '～にあって', 5, 6, TRUE, 1),
(458, 91, 'Bài 2.1 - ～皮切りに(して) / ～を皮切りとして', '～皮切りに(して) / ～を皮切りとして', 'Bắt đầu bằng (với ) thì', 'Diễn tả văn cảnh kể từ khi điều gì bắt đầu thì liên tiếp các hành động hay sự việc tương tự diễn ra, theo hướng phát triển tốt lên. Chú ý :Vế trước và sau là cùng 1 hành động và sự việc được xảy ra liên tiếp,câu văn mang nghĩa của sự phát triển đi lên Mẫu câu này không dùng để diễn đạt hiện tượng tự nhiên hay những điều không tốt.', '～皮切りに(して) / ～を皮切りとして', 5, 1, TRUE, 1),
(459, 91, 'Bài 2.2 - ～に至るまで', '～に至るまで', 'Đến cả( điều nhỏ nhất)', 'Dùng trong văn cảnh khi muốn nói ‘‘ ngay đến cả điều nhỏ nhặt nhất cũng được nhắc đến, để ý đến’’ Chú ý : Đi cùng với những câu từ có chút bất ngờ vì bình thường ít nhắc đến.Câu văn nhấn mạnh sự ảnh hưởng trên phạm vi rộng.', '～に至るまで', 5, 2, TRUE, 1),
(460, 91, 'Bài 2.3 - ～を限りに', '～を限りに', 'Cho đến hết (ngày/ tháng/ năm )…', 'Thông báo mốc thời gian kết thúc sự việc gì đó (cho đến hết ngày/tháng/ năm …). Chú ý : Danh từ đứng trước 「を限りに」là danh từ chỉ thời gian, thường là 「hôm nay、lần này、năm nay,…」', '～を限りに', 5, 3, TRUE, 1),
(461, 91, 'Bài 2.4 - ～をもって', '～をもって', 'Cho đến..(chấm dứt, kết thúc)', 'Thông báo về 1 sự việc liên tục được tiếp diễn từ trước nhưng ‘’ cho đến thời điểm N thì mọi chuyện kết thúc , dừng lại.’’ Chú ý : phần lớn đi kèm với danh từ chỉ thời gian , thời điểm , thời kì. Thường dùng trong các sự kiện trang trọng hay các nghi lễ, không dùng cho các sự việc xảy ra hàng ngày.', '～をもって', 5, 4, TRUE, 1),
(462, 91, 'Bài 2.5 - ～といったところだ', '～といったところだ', 'Cùng lắm cũng chỉ đến…', 'Diễn tả một mức độ nào đó không cao lắm, thường đi sau những con số biểu thị số lượng ít. Chú ý : Thường dùng với những từ chỉ số lượng hoặc mức độ nhỏ, không đáng kể.', '～といったところだ', 5, 5, TRUE, 1),
(463, 92, 'Bài 3.1 - ～をおいて', '～をおいて', 'Ngoài A ra thì không còn cái nào khác có thể', 'Dùng để diễn đạt ý muốn đề cao A là tốt nhất , giỏi nhất, sự lựa chọn đúng đắn nhất...Ngoài A ra thì không có cái nào, nơi đâu hoặc là ai có thể. Chú ý : Mẫu câu này thường có phần đằng sau là cụm từ 「ほか～いない・ない」', '～をおいて', 5, 1, TRUE, 1),
(464, 92, 'Bài 3.2 - ～ならでは', '～ならでは', 'Chỉ có thể là …', 'Dùng trong văn cảnh khi muốn nói rằng chỉ có N mới có thể làm được vậy.Nếu không phải N thì không thể. Chú ý : Mẫu câu diễn tả sự đánh giá cao của người nói đối với người/ vật được nhắc đến, thường dùng dưới dạng 「～な らではの～だ」/ 「～ならでは だ」', '～ならでは', 5, 2, TRUE, 1),
(465, 92, 'Bài 3.3 - ～にとどまらず', '～にとどまらず', 'Không chỉ dừng lại ở …, mà phạm vi còn lan rộng hơn', 'Dùng để diễn đạt ý muốn nói không chỉ giới hạn trong phạm vi mà còn ảnh hưởng và lan rọng ra ngoài. Chú ý : Đi kèm với từ ngữ thể hiện hiện tượng và phạm vi giới hạn.Vế sau 「にとどまらず」 biểu thị sự việc có phạm vi, mức độ rộng hơn, lớn hơn.', '～にとどまらず', 5, 3, TRUE, 1),
(466, 92, 'Bài 3.4 - ～はおろか', '～はおろか', 'Không chỉ ... mà ngay cả', 'Dùng trong văn cảnh khi muốn nói rằng đến B còn không làm được chứ đừng nói đến A. Chú ý :Dùng để nhấn mạnh cấp độ , trạng thái bằng cách đưa ra những điều đương nhiên , cả câu mang hàm ý tiêu cực, không tốt.Vế sau thường được sử dụng những từ mnag nghĩa nhấn mạnh như 「 も、 さえ、まで」v.', '～はおろか', 5, 4, TRUE, 1),
(467, 92, 'Bài 3.5 - ～もさることながら', '～もさることながら', 'Không những ... mà còn', 'Dùng muốn nhấn mạnh rằng không chỉ có A mà hơn thế nữa còn có cả B. Chú ý :Câu văn vế sau mang tính chất nhấn mạnh ‘’hơn thế nữa’’', '～もさることながら', 5, 5, TRUE, 1),
(468, 93, 'Bài 4.1 - ～なり・・・ なり', '～なり・・・ なり', 'A cũng được mà B cũng được', 'Dùng để diễn đạt ý muốn nói là A hay B cái nào cũng được cả , không cần quá coi trọng vấn đề. Chú ý : Ví dụ được đưa ra phải cũng chủng loại , câu văn đằng sau không không đi với thể QK. Thể hiện ý chí , nguyện vọng hay kêu gọi hành động.', '～なり・・・ なり', 5, 1, TRUE, 1),
(469, 93, 'Bài 4.2 - ～であれ・・・ であれ', '～であれ・・・ であれ', 'Dù là A hay B thì kết quả cũng giống nhau”', 'Dùng để diễn tả dù là A hay B đi nữa thì mọi chuyện vẫn như nhau. Chú ý : A và B là những từ/ cụm từ cùng nhóm nghĩa, có liên quan đến nhau.', '～であれ・・・ であれ', 5, 2, TRUE, 1),
(470, 93, 'Bài 4.3 - ～といい・・・ といい', '～といい・・・ といい', 'Ngay cả .. Hay là B ... thì cũng', 'Dùng để diễn đạt ý muốn nói ngay cả A hay là B thì cũng đều có đánh giá , kết luận chung . Chú ý : A và B là những từ/ cụm từ thuộc cùng một nhóm nghĩa, có liên quan đến nhau. Vế sau là đánh giá, nhận định của người nói (thường là dưới dạng tính từ)', '～といい・・・ といい', 5, 3, TRUE, 1),
(471, 93, 'Bài 4.4 - ～といい・・・ といい', '～といい・・・ といい', 'Tức là ...cho đến(mang ý nghĩa toàn bộ)', 'Dùng để diễn đạt ý muốn nói từ A đến B , tất cả tổng thể , oàn bộ đều... Chú ý : Các ví dụ đưa ra phải cùng loại . Thường có dạng kết hợp cùng bộ phận, cùng không gian , thời gian. Không chỉ thể hiện trạng thái mà còn thể hiện hành động . Thường dùng với nghĩa không tích cực.Không dùng trong câu văn kêu gọi hành động của người nói.', '～といい・・・ といい', 5, 4, TRUE, 1),
(472, 94, 'Bài 5.1 - ～いかんだ / ～いかんで (は)', '～いかんだ / ～いかんで (は)', 'phụ thuộc vào , dựa vào …', 'Dùng khi muốn nói dựa theo N mà tình hình có thể thay đổi theo hoặc dựa vào N mà 1 trạng thái được quyết định. Chú ý : Mẫu câu thường đi với những từ vựng thể hiện độ rộng và sự khác nhau như 考え 方、態度。。。Theo đó mà câu văn mang ý nghĩa thay đổi hay quyết định.', '～いかんだ / ～いかんで (は)', 5, 1, TRUE, 1),
(473, 94, 'Bài 5.2 - ～いかんにかかわらず・いかんによらず', '～いかんにかかわらず・いかんによらず', 'Không phụ thuộc vào … Không bị quyết định hay ảnh hưởng bởi …', 'Dùng khi muốn nói 1 việc được hình thành , quyết định l=không có liên quan hay bị ảnh hưởng bởi N Chú ý : Đi với những từ thể hiện độ rộng và sự khác nhau mang tính đa dạng . Theo sau đó là câu văn thể hiện ý nghĩa không bị ảnh hưởng hay chi phối.', '～いかんにかかわらず・いかんによらず', 5, 2, TRUE, 1),
(474, 94, 'Bài 5.3 - ～をものともせず（に）', '～をものともせず（に）', 'Bất chấp/ Vượt lên/ Mặc cho (hoàn cảnh khó khăn) …', 'Dùng trong văn cảnh khi muốn nói nếu bình thường nếu rơi vào hoàn cảnh như vậy sẽ dễ đầu hàng/ từ bỏ nhưng vẫn vượt qua và bước tiếp. Chú ý : Mẫu câu thường dùng để ca ngợi sự dũng cảm, nghị lực của ai đó. Không dùng để nói về bản thân mình. -Đi cùng với nhiều từ có ý nghĩa gây thể hiện sự cản trở ngại lớn như 台風、病気、危険、。。。', '～をものともせず（に）', 5, 3, TRUE, 1),
(475, 94, 'Bài 5.4 - ～をよそに', '～をよそに', 'Không quan tâm/ Mặc kệ…', 'Dùng trong văn cảnh khi muốn nói điều đó không mấy quan trọng , không để ý đến, hành động vẫn tiếp tục được diễn ra. Chú ý : Đi kèm với bối cảnh xung quanh . Vế sau là thái độ coi thường , phớt lờ đi trở ngại đó để hành động Không dùng mẫu câu này để nói về bản thân mình.', '～をよそに', 5, 4, TRUE, 1),
(476, 94, 'Bài 5.5 - ～ならいざしらず', '～ならいざしらず', 'A thì đã đành/ A thì không nói làm gì nhưng B thì…', 'Dùng trong văn cảnh khi muốn nói rằng nếu là .. thì đúng là như vậy , nhưng vì là tình trạng trạng hoàn toàn khác nên kết quả cũng khác.Mẫu câu thể hiện sự ngạc nhiên hoặc bất mãn của người nói. Chú ý : Đi kèm với với từ vựng thể hiện sự cực đoan.Vế sau thể hiện sự đối lập , cảm xúc bất mãn , ngán ngẩm.', '～ならいざしらず', 5, 5, TRUE, 1),
(477, 95, 'Bài 6.1 - ～んばかりだ', '～んばかりだ', 'Cứ như thể đến mức/ Giống như là', 'Dùng khi nói sự việc xảy ra đến mức giống hệt như là...(mang nghĩa nói quá lên 1 chút) Chú ý : Thường đi kèm với cách nói thể hiện thực tế thì không đến mức là như vậy nhưng cũng gần ở mức độ đó.Toàn câu thể hiện cấp độ lớn hơn mức bình thường.', '～んばかりだ', 5, 1, TRUE, 1),
(478, 95, 'Bài 6.2 - ～とばかり（に）', '～とばかり（に）', 'Cứ như thể là nói “…”', 'Dùng để diễn tả văn cảnh đó không nói ra bằng lời nhưng nhìn bầu không khí, ánh mắt , cử chỉ... như là đang muốn nói là như vậy. Chú ý : Thường đi kèm với những câu nói thể hiện sự thông báo như 帰れ、だめ だ、...Sử dụng trong trường hợp nói về dán vẻ của người khác, không dùng cho bản thân người nói.', '～とばかり（に）', 5, 2, TRUE, 1),
(479, 95, 'Bài 6.3 - ～ともなく / ～ともなしに', '～ともなく / ～ともなしに', 'Thực sự là không cố ý, vô tình', 'Dùng để diễn tả rằng bản thân làm gì đó một cách tự nhiên, không có ý thức, không có mục đích. . Chú ý : Hay dùng với những động từ chỉ ý chí như 「見る/ 聞く/ 待つ v.v」 -Động từ thường được lặp lại trước và sau 「ともなく/ とも なしに」', '～ともなく / ～ともなしに', 5, 3, TRUE, 1),
(480, 95, 'Bài 6.4 - ～ながらに（して）', '～ながらに（して）', 'Từ khi…/ Trong khi (trạng thái giữ nguyên không thay đổi)', 'Dùng để diễn tả trạng thái không thay đổi , vẫn giữ nguyên hình thái như ban đầu. Chú ý : Chỉ giới hạn sử dụng với 1 số câu nhất định.涙ながら に được hiểu là 泣きながら', '～ながらに（して）', 5, 4, TRUE, 1),
(481, 95, 'Bài 6.5 - ～きらいがある', '～きらいがある', 'Có chiều hướng, có khuynh hướng, hay làm gì đó (không tốt)', 'Dùng để nói về ai đó có khuynh hướng , có thói quen , tính cachs không tốt. Chú ý : Phần lớn là để đánh giá người khác , không dùng với bản thân người nói.Toàn câu không thể hiện cách nói mạnh mẽ mà đi kèm với các từ どうも、すこし、ともすれ ば。。。để giảm bớt', '～きらいがある', 5, 5, TRUE, 1),
(482, 96, 'Bài 7.1 - ～がてら', '～がてら', 'Tranh thủ', 'Dùng trong trường hợp muốn tranh thủ sử dụng cơ hội để thực hiện hành động 1 thì thực hiện hành động 2. Chú ý : Thường đi kèm với những danh từ chỉ sự chuyển động như 散歩、買い物', '～がてら', 5, 1, TRUE, 1),
(483, 96, 'Bài 7.2 - ～かたがた', '～かたがた', 'Làm A thì cũng là làm B', 'Dùng trong trường hợp diễn tả việc mình thực hiện hành động là có cả mục đích khác đi đèm(Liên kết câu theo quan hệ chính – chính) Chú ý : Mẫu câu hay dùng kèm với những động từ chỉ sự di chuyển 散歩、買い物', '～かたがた', 5, 2, TRUE, 1),
(484, 96, 'Bài 7.3 - ～かたわら', '～かたわら', 'Bên cạnh việc… thì còn', 'Dùng khi nói bên cạnh công việc chính thì còn làm thêm việc khác/ hoạt động khác nữa. Chú ý : Thường đi kèm với những từ thể hiện công việc chính , vế sau thể hiện 1 hoạt động xã hội khác hoàn toàn so với công việc chính đang làm.', '～かたわら', 5, 3, TRUE, 1),
(485, 97, 'Bài 8.1 - N の+ TTT～だ+ の / ～ところを', 'N の+ TTT～だ+ の / ～ところを', 'Vào lúc, trong lúc, trong khi ( vậy mà ) …', 'Dùng trong trường hợp muốn xin lỗi người khác vì trong hoàn cảnh ,tinh tế …như vậy mà mình lại làm phiền. Chú ý : Kết hợp với những từ thể hiện tình trạng tiếp tục tiếp diễn . Đây là cách nói mang tính lễ nghĩa khi mình làm phiền đối phương nên thường đi với câu văn mang nghĩa cảm tạ hoặc xin lỗi.', 'N の+ TTT～だ+ の / ～ところを', 5, 1, TRUE, 1),
(486, 97, 'Bài 8.2 - ～ものを', '～ものを', 'nếu mà … thì đã …, nhưng…', 'Dùng trong trường hợp muốn nói nếu như đúng theo trình tự thì mọi việc sẽ trọn vẹn như vậy mà sự thật thì lại không như vậy. Chú ý : Câu mnag theo cảm xúc tiếc nuối , bất mãn của người nói.Đằng sau là câu giải thích về sự thật ( mẫu câu cũng dùng để kiểm điểm bản thân)', '～ものを', 5, 2, TRUE, 1),
(487, 97, 'Bài 8.3 - ～とはいえ', '～とはいえ', 'Mặc dù… nhưng …”', 'Dùng trong trường hợp muốn nói rằng cái việc được nhắc đến có lẽ là sự thật nhưng dù là như vậy cũng... Chú ý : Câu văn thể hiện việc người nói nghĩ đó là sự thật.Vế sau thể hiện nghĩa không đơn thuần chỉ là sự thật hoặc kèm theo câu văn mang đánh giá của người nói', '～とはいえ', 5, 3, TRUE, 1),
(488, 97, 'Bài 8.4 - ～といえども', '～といえども', 'Dù … đi chăng nữa, thì …', 'Dùng trong trường hợp muốn nói rằng dù sự thật có là như vậy đi nữa thì việc xảy ra cũng không thể coi là bình thường. Chú ý : Mẫu câu này chủ yếu dùng trong văn viết hay hoàn cảnh trang trọng. Hay dùng kèm những phó từ như 「いか に/ たとえ/ どんな」', '～といえども', 5, 4, TRUE, 1),
(489, 97, 'Bài 8.5 - ～と思いきや', '～と思いきや', 'Cứ nghĩ là … nhưng sự thực thì lại khác', 'Dùng trong trường hợp muốn nói là bản than mình nghĩ là như thế nhưng lại không phải vậy. Chú ý : Câu văn thể hiện sự ngạc nhiên vì sự thật trái với dự tưởng của người nói.Trước と 思いきやđôi khi có thêm か. Vế sau thể hiện kết quả trái ngược với dự tưởng.', '～と思いきや', 5, 5, TRUE, 1),
(490, 98, 'Bài 9.1 - ～とあれば', '～とあれば', 'Nếu … thì…', 'Dùng trong trường hợp muốn nói rằng nếu là điều kiện đặc biệt thì vế sau sẽ là 1 trạng thái hoặc 1 hành động vì điều kiện đặc biệt đó. Chú ý : Vế sau thường mnag nghĩa thể hiện sự phán đoán , ý hướng hay nguyện vọng của người nói.', '～とあれば', 5, 1, TRUE, 1),
(491, 98, 'Bài 9.2 - ～たら最後 / ～たが最後', '～たら最後 / ～たが最後', 'Nếu … thì kết cục là …” (kết quả không tốt)', 'Dùng trong trường hợp muốn nói rằng nếu làm hành động ở vế trước thì nhất định sẽ nhận lấy kết cục xấu ở vế sau. Chú ý :Sử dụng cho cả thực tế lẫn trường hợp giả định, vế sau là câu văn thể hiện suy nghĩ về 1 kết cục xấu của người nói.', '～たら最後 / ～たが最後', 5, 2, TRUE, 1),
(492, 98, 'Bài 9.3 - A な + TTT ～だ+な・である / NTTT～だ + である / ～ようでは', 'A な + TTT ～だ+な・である / NTTT～だ + である / ～ようでは', 'Như thế …thì (cả 2 vế đều là kết quả xấu)', 'Dùng trong trường hợp muốn nói rằng với trạng thái không tốt như vậy thì cũng mang lại kết quả không tốt. Chú ý : Câu văn biểu hiện sự thực không mong muốn .Vế sau là câu văn phỏng đoán về điều không mong muốn có thể xảy ra.', 'A な + TTT ～だ+な・である / NTTT～だ + である / ～ようでは', 5, 3, TRUE, 1),
(493, 98, 'Bài 9.4 - ～なしに（は） / ～なしでは / ～なくして（は）', '～なしに（は） / ～なしでは / ～なくして（は）', 'Nếu không …, thì không thể … Nếu không có', 'Dùng trong trường hợp muốn nói rằng giả sử không nhờ có vế 1 thì không thể có được những thứ ở vế 2. Chú ý : Câu văn thể hiện sự đánh giá của người nói về việc nhất định phải cần có A thì mới có được B. Nói lên suy nghĩ khẳng định là phải cần có A. Vế sau ở dạng phủ định.', '～なしに（は） / ～なしでは / ～なくして（は）', 5, 4, TRUE, 1),
(494, 98, 'Bài 9.5 - ～くらいなら', '～くらいなら', 'Nếu mà ... Thì thà ... Còn hơn', 'Dùng trong trường hợp muốn nói rằng làm hành động ở vế sau còn hơn là phải chịu hoàn cảnh không mong muốn như vế 1. Chú ý : Câu văn thể hiện suy nghĩ có phần ác cảm của người nói. Vế sau thể hiện hành động mà người nói nghĩ là làm như vậy sẽ tốt hơn.', '～くらいなら', 5, 5, TRUE, 1),
(495, 99, 'Bài 10.1 - -A い ～かろう / -A な / N ～だろう・であろう / ～と / が / ～と（も）/ が / ～であろう + と（も）/ が', '-A い ～かろう / -A な / N ～だろう・であろう / ～と / が / ～と（も）/ が / ～であろう + と（も）/ が', 'Cho dù … thì cũng không liên quan/ không ảnh hưởng gì“', 'Thể hiện ý muốn nói rằng cho dù có ... Thì cũng không liên quan, không bị ảnh hưởng. Chú ý : Câu đằng sau không bị ảnh hưởng, tác động bởi điều kiện vế trước. Phần lớn thể hiện sự quyết đoán của người nói. Thêm vào đó là thường sử dụng với những từ như たとえ・いかに・どんなに (dù thế nào/ dù … bao nhiêu đi nữa)', '-A い ～かろう / -A な / N ～だろう・であろう / ～と / が / ～と（も）/ が / ～であろう + と（も）/ が', 5, 1, TRUE, 1),
(496, 99, 'Bài 10.2 - -V 意向 ～と・が ＋ V る', '-V 意向 ～と・が ＋ V る', '（VII III ＝ V る ます ＋ま い する＝すまい するまい） ～まい＋と が Dù có … hay không thì vẫn', 'Thể hiện ý muốn nói rằng cho dù có làm hay không làm thì vẫn không liên quan, không bị ảnh hưởng. Chú ý : Động từ giống nhau được lặp lại, câu mang nghĩa cho dù điều kiện vế trước là gì cũng không bị ảnh hưởng. Thường đi kèm với sắc thái thể hiện ý chí quả quyết hay phán đoán của người nói.', '-V 意向 ～と・が ＋ V る', 5, 2, TRUE, 1),
(497, 99, 'Bài 10.3 - ～であれ / ～であろうと', '～であれ / ～であろうと', 'Giả sử, cho dù ... Thì cũng (giả định + Nghi vấn)', 'Dùng trong trường hợp giả sử vế 1 có diễn ra thì vế 2 cũng không ảnh hưởng, không liên quan. Chú ý : Câu đằng sau không bị ảnh hưởng, tác động bởi điều kiện vế trước. Phần lớn thể hiện sự quyết đoán của người nói. Thêm vào đó là thường sử dụng với những từ như たとえ・どんな.', '～であれ / ～であろうと', 5, 3, TRUE, 1),
(498, 99, 'Bài 10.4 - ～ところで', '～ところで', 'Dù ... Thì cũng (kết quả vô ích, vô nghĩa)', 'Để nói lên rằng cho dù có thử làm đi chăng nữa hay cho dù có ở trạng thái như nào đi nữa thì cũng không có nghĩa lý, vô ích. Chú ý : Vế sau là câu văn thể hiện phán đoán mang tính phủ định, không đi kèm với câu văn thể hiện nguyện vọng, ý chí, hay kêu gọi hành động. Thường kết hợp với いくら、ど んなに、いまさら.', '～ところで', 5, 4, TRUE, 1),
(499, 99, 'Bài 10.5 - -A な ～なら＋ A な / ～で', '-A な ～なら＋ A な / ～で', 'Nếu mà ... Thì thà ... Còn hơn', 'Để nói lên rằng cho dù có ở hoàn cảnh như vậy thì vẫn như những gì mình tưởng tượng là không tốt hoặc không xấu. Chú ý : Các từ ngữ giống nhau được lặp lại.', '-A な ～なら＋ A な / ～で', 5, 5, TRUE, 1),
(500, 100, 'Bài 11.1 - ～べく', '～べく', 'Để...nên làm.. Vì mục đích … nên làm, quyết làm … する ＝ するべく すべ く', 'Dùng trong văn viết, là cách nói diễn đạt ý định/quyết tâm sẽ làm để đạt được mục đích nào đó. Chú ý : Đi với động từ mang tính ý chí, vế trước và sau có cùng chung chủ ngữ. Không dùng với câu văn kêu gọi hành động.', '～べく', 5, 1, TRUE, 1),
(501, 100, 'Bài 11.2 - ～んがため（に）', '～んがため（に）', 'Với mục đích để', 'Nói về việc thực hiện hành vi để đạt được 1 mục đích nào đó. Chú ý : Đi với những từ mang ý nghĩa thể hiện mục đích quan trọng, đằng sau là câu thể hiện hành vi có tính ý chí. Không dùng với mẫu câu kêu gọi hành động, chủ ngữ vế trước và sau giống nhau. Không dùng với mục đích thường ngày.', '～んがため（に）', 5, 2, TRUE, 1),
(502, 100, 'Bài 11.3 - ～をもって', '～をもって', 'Bởi , bằng cách', 'Miêu tả việc thực hiện hành vi bằng 1 cách thức nào đó. Chú ý : Không sử dụng với phương pháp, công cụ mang tính cụ thể và đời sống thường ngày. Như ví dụ 3 sử dụng をも ってすれば là cách nói thể hiện ý nghĩa đánh giá cao về năng lực ...', '～をもって', 5, 3, TRUE, 1),
(503, 101, 'Bài 12.1 - ～ばこそ', '～ばこそ', 'Chính vì/ Do … mới dám/ mới có thể/ mới phải …', 'Diễn tả ý muốn nói chính vì A mà B như vậy. Mang nghĩa nhấn mạnh lý do trực tiếp tác động đến vế 1. Chú ý : Vế sau hay dùng với mẫu câu ～のだ・のです.', '～ばこそ', 5, 1, TRUE, 1),
(504, 101, 'Bài 12.2 - ～とあって', '～とあって', 'Vì/ Do …', 'Dùng trong trường hợp muốn nói, do 1 hoàn cảnh đặc biệt nào đó mà đương nhiên kết quả xảy ra cũng đặc biệt. Chú ý : Đi kèm với từ vựng thể hiện hoàn cảnh đặc biệt khác với thường ngày. Vế sau là kết quả đương nhiên có được từ hoàn cảnh đặc biệt này. Không dùng để nói về bản thân người nói.', '～とあって', 5, 2, TRUE, 1),
(505, 101, 'Bài 12.3 - ～ではあるまいし', '～ではあるまいし', 'Vì không phải ... Nên', 'Dùng trong trường hợp muốn nói, nếu đúng là N thì có thể hiểu được nhưng vì không phải là N nữa nên ... Chú ý : Câu sau đi kèm sắc thái phủ định hiện trạng, thể hiện chủ trương, phán đoán của người nói. Như ví dụ 4 có thể không kết hợp với N.Ngoài danh từ thì có thể dùng theo cụm như ～わけではあるまいし hay ～のではあるまいし.', '～ではあるまいし', 5, 3, TRUE, 1),
(506, 101, 'Bài 12.4 - ～手前', '～手前', 'Chính vì', 'Dùng trong trường hợp muốn nói rằng chính vì lý do ... mà mình không làm thì sẽ bị đánh giá, mất uy tín. Chú ý : Dùng khi muốn nói lên sự suy nghĩ về việc đánh giá của xã hội và người khác. Vế sau đi kèm với mẫu câu thể hiện việc hành động của người nói bị hạn chế như わけにはい かない、なければならない、ざ るを得ない', '～手前', 5, 4, TRUE, 1),
(507, 101, 'Bài 12.5 - A な- TTT ～だ＋な・であるN (の)/ である / ～ゆえ(に)', 'A な- TTT ～だ＋な・であるN (の)/ である / ～ゆえ(に)', 'Là lý do, nguyên nhân', 'Dùng trong trường hợp muốn nói rằng vì lý do ... Nên... Chú ý : Dùng trong thư từ hoặc công văn. Không dùng trong đời sống thường ngày.', 'A な- TTT ～だ＋な・であるN (の)/ である / ～ゆえ(に)', 5, 5, TRUE, 1),
(508, 102, 'Bài 13.1 - ～にかたくない', '～にかたくない', 'Không khó để có thể', 'Diễn tả ý muốn nói không cần phải tận mắt chứng kiến đi nữa thì vẫn có thể hiểu được , hoặc không khó để có thể hiểu, cảm nhận được. Chú ý : Giới hạn dùng với những từ mang nghĩa thể hiện hoạt động của cảm xúc như 想 像する、察する、理解す る。。。', '～にかたくない', 5, 1, TRUE, 1),
(509, 102, 'Bài 13.2 - ～可能の動詞否定形 (thể khả năng', '～可能の動詞否定形 (thể khả năng', 'dạng phủ định) Dù rất muốn nhưng không thể', 'Diễn tả ý muốn nói dù muốn làm nhưng vì do 1 lý do, sự tình nào đó mà không thể làm được. Chú ý : Vế trước và sau cùng sử dụng động từ giống nhau. Động từ ở vế sau chia về động từ thể khả năng. に～ない diễn tả sự tình mang tính tâm lý. ようにも～ない diễn tả sự tình mang tính vật lý.', '～可能の動詞否定形 (thể khả năng', 5, 2, TRUE, 1),
(510, 102, 'Bài 13.3 - ～はいられない', '～はいられない', 'Không được , Không thể …', 'Diễn tả ý muốn nói đang trong hoàn cảnh này thì không được, không thể.. Chú ý : Thể hiện cảm xúc phải tiếp tục hành động ngay lập tức. Chủ ngữ là ngôi số 1.', '～はいられない', 5, 3, TRUE, 1),
(511, 102, 'Bài 13.4 - ～べくもない', '～べくもない', 'Làm sao có thể, không thể', 'Diễn tả ý muốn nói rằng ở trong hoàn cảnh đó thì đương nhiên là không thể ... Chú ý : Thường dùng với những động từ thể hiện cảm xúc, tâm lý như 考える、想像す る、知る. chế như わけにはい かない、なければならない、ざ るを得ない', '～べくもない', 5, 4, TRUE, 1),
(512, 102, 'Bài 13.5 - ～べからず / ～べからざる ＋', '～べからず / ～べからざる ＋', 'N Không thể, không được', 'Diễn tả ý muốn cấm đoán không được phép thực hiện hành động nào đó. Chú ý : Mẫu câu này chỉ sử dụng với nội dung thông báo hay trên bảng chú ý. べからず dùng trong văn viết, べからざる dùng trong văn nói.', '～べからず / ～べからざる ＋', 5, 5, TRUE, 1),
(513, 102, 'Bài 13.6 - ～まじき ＋ N', '～まじき ＋ N', 'Không nên, không được có', 'Diễn tả ý muốn nói nếu đứng ở vị trí, lập trường, phương diện đạo đức thì không được làm như vậy. Chú ý : Đằng sau nhất định phải có N đi kèm. Chỉ sử dụng với cách nói đã được quy định sẵn.', '～まじき ＋ N', 5, 6, TRUE, 1),
(514, 103, 'Bài 14.1 - ～ときたら', '～ときたら', 'Nói về, nói đến', 'Diễn tả việc nhắc đến N thì có đặc điểm, tính cách gì đó không tốt. Chú ý : Dùng trong văn nói, nói về sự bất mãn của bản thân với những vấn đề được đưa ra và bất mãn với những người, vật xung quanh mình. Vế sau mang nghĩa tiêu cực thể hiện tự trách móc, không hài lòng. Không dùng với câu văn mang tính ý chí và kêu gọi hành động.', '～ときたら', 5, 1, TRUE, 1),
(515, 103, 'Bài 14.2 - ～ともなると / ～ともなれば', '～ともなると / ～ともなれば', 'Nếu là ... Thì', 'Diễn tả muốn nói rằng khi vị trí và cấp độ dần cao hơn thì sẽ dần trở thành 1 trạng thái khác. Chú ý : Đi cùng với những từ thể hiện cấp độ và từ diễn tả đó là trường hợp đặc biệt. Vế sau muốn nói đến trạng thái đương nhiên sẽ xảy ra nếu đạt đến cấp độ được nhắc tới ở vế trước. Không đi với câu thể hiện ý chí, hay kêu gọi hành động của người nói.', '～ともなると / ～ともなれば', 5, 2, TRUE, 1),
(516, 103, 'Bài 14.3 - ～ともあろう', '～ともあろう', '＋ N Với cương vị là ... Nhưng', 'Dùng khi muốn nói rằng đang ở vị trí có năng lực và trách nhiệm vô cùng to lớn như vậy mà lại có những hành động khó chấp nhận được. Chú ý : Thể hiện sự bất mãn, ngạc nhiên với những hành động mà ngay cả người bình thường cũng biết là không nên làm. Như ví dụ 4 nói lên cảm tưởng yêu cầu người đứng ở cương vị đó nên có những hành động xứng đáng. Đi với những danh từ thể hiện sự đành giá cao từ người nói.', '～ともあろう', 5, 3, TRUE, 1),
(517, 103, 'Bài 14.4 - ～たるもの（は）', '～たるもの（は）', 'Với cương vị là ... Thì phải', 'Dùng khi muốn nói rằng khi đứng ở cương vị có năng lực và trách nhiệm vô cùng to thì nên làm những hành động xứng đáng với cương vị đó. Chú ý : Đi với những N thể hiện cương vị, chức vụ, trách nhiệm cao. Phía sau là hành động tương xứng, nên làm khi ở cương vị đó.', '～たるもの（は）', 5, 4, TRUE, 1),
(518, 103, 'Bài 14.5 - A な- TTT ～だ', 'A な- TTT ～だ', 'N ～ なりに Trong hoàn cảnh', 'Dùng khi muốn nói rằng trong phạm vi giới hạn thì sẽ cố gắng nỗ lực hết mình. Chú ý : Đi với những từ thể hiện cảm giác ở mức độ không quá lớn của người nói. Vế sau là hành động, thái độ đối với hoàn cảnh đó. Ví dụ số 5 là cách nói được sử dụng rộng rãi.', 'A な- TTT ～だ', 5, 5, TRUE, 1),
(519, 104, 'Bài 15.1 - ～だ ＋な・である / ～のにひきかえ', '～だ ＋な・である / ～のにひきかえ', 'So với ... Thì (ngược lại)', 'Diễn tả 2 chủ đề có sự tương phản trái ngược nhau. So với A thì ngược lại B (mang tính chất hoặc tốt, hoặc xấu) Chú ý : Không dùng để so sánh những sự việc mang tính chất đơn giản mà so sánh cả 2 đối tượng để có đánh giá chủ quan là tốt hay xấu. Không dùng để so sánh ước lượng.', '～だ ＋な・である / ～のにひきかえ', 5, 1, TRUE, 1),
(520, 104, 'Bài 15.2 - ～にもまして', '～にもまして', 'Hơn, nhiều hơn', 'Diễn tả nghĩa tại thời điểm hiện tại sự việc xảy ra có cấp độ cao hơn, nhiều hơn, quan trọng hơn thời điểm trước đây Chú ý : Đi với danh từ thể hiện việc xảy ra tại thời điểm trước hoặc những việc mang tính chất thường ngày. Như ví dụ 4 đi kèm từ để hỏi thể hiện cấp độ cao hơn hẳn. Không dùng với câu phủ định.', '～にもまして', 5, 2, TRUE, 1),
(521, 104, 'Bài 15.3 - ～までも', '～までも', 'Dù không phải ... Nhưng', 'Diễn tả trạng thái rằng chưa thể đạt đến được mức độ đó nhưng đang thấp hơn mức đấy 1 chút. Chú ý : Đi kèm với danh từ thể hiện trạng thái cực đoan, và trạng thái lý tưởng. Phía sau là câu văn thể hiện cấp độ thấp hơn mức độ nói ở vế trước 1 chút với cảm giác đã có thể hài lòng, mãn nguyện.', '～までも', 5, 3, TRUE, 1),
(522, 105, 'Bài 16.1 - ～に至って / ～に至っても', '～に至って / ～に至っても', 'Cho đến khi ... Đến tận khi… mới…', 'Diễn tả 1 việc tiến triển cho đến 1 ngưỡng, và cuối cùng đã trở thành 1 trạng thái. Chú ý : Đi kèm với từ ngữ thể hiện trạng thái mà bình thường không thể nghĩ ra. Sau に至って là trạng thái tiến triển và cuối cùng cũng hình thành kết quả. Sau に至っても thì dù có tiến triển như thế nào đi nữa cũng không đi đến đâu.', '～に至って / ～に至っても', 5, 1, TRUE, 1),
(523, 105, 'Bài 16.2 - ～に至っては', '～に至っては', 'Riêng .., Đặc biệt với', 'Dùng khi muốn nhấn mạnh 1 trạng thái bằng cách đưa ra 1 ví dụ điển hình mang tính chất cực đoan. Chú ý : Câu thể hiện đánh giá xấu, đi kèm với ví dụ ở cấp độ cực đoan. Đằng sau là câu nói lên trạng thái của vấn đề.', '～に至っては', 5, 2, TRUE, 1),
(524, 105, 'Bài 16.3 - ～始末だ', '～始末だ', 'Rút cuộc, kết cục là', 'Dùng khi muốn diễn tả việc trải qua trạng thái xấu và cuối cùng nhận được 1 kết cục không tốt. Chú ý : Câu văn thể hiện kết cục xấu. Thông thường sẽ giải thích về 1 tình trạng xấu tiếp diễn và theo sau đó là nhấn mạnh kết cục không tốt bằng つ いに、とうとう、まで。', '～始末だ', 5, 3, TRUE, 1),
(525, 105, 'Bài 16.4 - ～っぱなしだ', '～っぱなしだ', 'Để nguyên, giữ nguyên', 'Dùng khi muốn diễn tả 1 trạng thái liên tục tiếp diễn mà bình thường hiếm khi xảy ra. Chú ý : Phần lớn diễn tả trạng thái không tốt. Nhiều trong số đó đi kèm sự trách móc, bất mãn。', '～っぱなしだ', 5, 4, TRUE, 1),
(526, 106, 'Bài 17.1 - ～たりとも…ない', '～たりとも…ない', 'Dù chỉ là, thậm chí là ... Cũng không', 'Diễn tả việc nhấn mạnh 1 điều gì đó ở mức độ tối thiểu thấp nhất cũng không xảy ra. Chú ý : Đi với đơn vị thấp nhất là số 1 nhưng không dùng với đơn vị đo quá lớn như １ 年、１トン . Như ở ví dụ số 4 何 人たりとも là cách nói quen thuộc.', '～たりとも…ない', 5, 1, TRUE, 1),
(527, 106, 'Bài 17.2 - ～すら', '～すら', 'Thậm chí, ngay cả', 'Ý muốn nói rằng ngay cả trường hợp được đưa ra còn thế thì những cái khác cũng đương nhiên là tương tự. Chú ý : Không có.', '～すら', 5, 2, TRUE, 1),
(528, 106, 'Bài 17.3 - ～だに', '～だに', 'Thậm chí, ngay cả', 'Ý muốn nói rằng ngay cả trong suy nghĩ, tưởng tượng, giấc mơ ... cũng đã quá kinh khủng . Chú ý : Thường chỉ đi với những từ vựng giới hạn như 想像 する、考える、聞く。。。', '～だに', 5, 3, TRUE, 1),
(529, 106, 'Bài 17.4 - ～にして', '～にして', 'Cỡ tầm, khoảng', 'Ý muốn nói rằng với mức độ, trình độ cao như này thì có thể hợp hoặc không phù hợp với 1 ai đó. Chú ý : Đi với những từ vựng mang cấp độ cao, đặc biệt. Câu sau thể hiện việc hợp hoặc không hợp với N', '～にして', 5, 4, TRUE, 1),
(530, 106, 'Bài 17.5 - ～あっての ＋ N', '～あっての ＋ N', 'Cần phải có', 'Ý muốn nói rằng cần phải có A thì mới hình thành B. Chú ý : Nhấn mạnh vào việc thể hiện sự biết ơn. Đi kèm với câu văn thể hiện việc cần thiết phải có N, không thể thiếu đi N.', '～あっての ＋ N', 5, 5, TRUE, 1),
(531, 106, 'Bài 17.6 - ～＋からある / からする / からの＋', '～＋からある / からする / からの＋', 'N Cỡ tầm, số lượng', 'Ý muốn nói về số lượng hay mức độ ở trên mức mình nhắc tới. Chú ý : Nhấn mạnh về lượng và số lượng. Vế sau đi với N phù hợp với số lượng đằng trước. Không dùng với số lượng ít và thời gian. Khi nói về cân nặng, độ to, khoảng cách dùng からあ る・からの. Khi nói về giá cả dùng からする、khi nói về số lượng dùng からの。', '～＋からある / からする / からの＋', 5, 6, TRUE, 1),
(532, 107, 'Bài 18.1 - ～までもない', '～までもない', 'Không cần ... (cũng chẳng sao)', 'Diễn tả ý muốn nói cho dù không có làm V đi chăng nữa thì cũng khá ổn rồi nên không cần thiết phải mất công. Chú ý : Câu văn đi kèm với động từ thể hiện hành vi có ý chí.', '～までもない', 5, 1, TRUE, 1),
(533, 107, 'Bài 18.2 - ～までだ ・ までのことだ', '～までだ ・ までのことだ', '(Vì)… nên đành…, Chỉ còn cách', 'Diễn tả ý muốn nói rằng không còn phương pháp nào khác nên chỉ còn cách cố gắng. Chú ý : Thể hiện sự kiên quyết của người nói rằng để làm việc như vậy thì không phải là vấn đề. Thường sử dụng nhiều với câu văn mang nghĩa điều kiện. Không sử dụng cho quá khứ mà chỉ dùng cho hiện tại và tương lai .', '～までだ ・ までのことだ', 5, 2, TRUE, 1),
(534, 107, 'Bài 18.3 - ～それまでだ', '～それまでだ', 'Là hết, là xong', 'Diễn tả ý muốn nói rằng, giả sử nếu điều đó xảy ra thì tất cả đều tiêu tan, ngoài điều đó ra thì không thể làm thêm được gì. Chú ý : Thường sử dụng kết hợp với ～ても.', '～それまでだ', 5, 3, TRUE, 1),
(535, 107, 'Bài 18.4 - ～には当たらない', '～には当たらない', 'Không cần phải quá ... Ý nói đó là chuyện bình thường', 'Diễn tả ý muốn nói rằng, chuyện cũng không đến mức phải như thế hay việc như thế thì không thích hợp. Chú ý : Là cách nói kìm chế đối phương để không có những phản ứng mang tính cảm xúc hay không có những đánh giá quá mức. Đi với động từ thể hiện đánh giá, cảm xúc như 驚く、悲観する、非難する.', '～には当たらない', 5, 4, TRUE, 1),
(536, 107, 'Bài 18.5 - ～でなくてなんだろう（か）', '～でなくてなんだろう（か）', 'Ngoài sức tưởng tượng', 'Diễn tả ý muốn nói rằng không nghĩ đến chuyện ngoài sức tưởng tượng của mình. Chú ý : Là cách nói cứng nhắc và có phần hơi quá. Thể hiện cảm xúc ngưỡng mộ, cảm động, đau buồn.', '～でなくてなんだろう（か）', 5, 5, TRUE, 1),
(537, 108, 'Bài 19.1 - ～に足る', '～に足る', 'Xứng đáng, đủ để', 'Diễn tả ý muốn nói về 1 việc hay 1 vật nào đó đủ để có thể... Chú ý : Thường được sử dụng dưới dạng bổ sung ý nghĩa cho danh từ. Với dạng phủ định thì sẽ không phủ định thành 足りない mà sẽ phủ định ở cuối câu như ví dụ 2. 取るに 足りない là cách nói phổ biến mang nghĩa ‘‘Không đủ giá trị để đưa lên’’.', '～に足る', 5, 1, TRUE, 1),
(538, 108, 'Bài 19.2 - ～に堪える/ ～に堪えない', '～に堪える/ ～に堪えない', 'Có giá trị, không thể chịu đựng', 'Diễn tả ý muốn nói về 1 việc nào đó có giá trị hoặc ở 1 tình cảnh nào đó không thể chấp nhận được. Chú ý : Thường giới hạn với những từ vựng đi kèm như 見る、聞く、鑑賞、批判.', '～に堪える/ ～に堪えない', 5, 2, TRUE, 1),
(539, 108, 'Bài 19.3 - ～といったらない', '～といったらない', 'Cực kì là', 'Dùng để diễn tả mức độ cực đoan không thể nói ra bằng lời. Chú ý : Thể hiện sự ngạc nhiên ở mức độ cực đoan. Thường thêm さ vào tính từ để danh từ hóa tính từ như すばら しさ、りっぱさ... Cũng có trường hợp lược bỏ ない như ở ví dụ 3.', '～といったらない', 5, 3, TRUE, 1),
(540, 108, 'Bài 19.4 - ～かぎりだ', '～かぎりだ', 'Rất', 'Dùng để nói lên cảm xúc về 1 việc mang hàm ý rất đỗi ... Chú ý : Không dùng để nói về tính chất của sự vật, sự việc. Nói lên cảm xúc của người nói. Đi với tính từ biểu thị cảm xúc.', '～かぎりだ', 5, 4, TRUE, 1),
(541, 108, 'Bài 19.5 - ～極まる', '～極まる', 'Cực kì, rất', 'Dùng để nói về trạng thái của sự vật, sự việc đến mức độ cực hạn. Chú ý : Thường đi cùng tính từ đuôi な mang nghĩa tiêu cực. Ví dụ số 3 là cách nói thông dụng, thể hiện mức độ cảm động mang tính nhất thời.', '～極まる', 5, 5, TRUE, 1),
(542, 108, 'Bài 19.6 - TTT ～だ / ～とは', 'TTT ～だ / ～とは', 'Vô cùng', 'Dùng để về 1 sự việc nào đó rất bất ngờ, tồi tệ, rất đỗi ... Chú ý : Dùng để nhấn mạnh cảm xúc chán nản, khâm phục hay bất ngờ của người nói đối với 1 sự thật. Đi kèm câu văn thể hiện sự thật bất ngờ của người nói. Đi sau đó là câu văn thể hiện cảm tưởng. Không sử dụng để nói về sự tự tin của người nói.', 'TTT ～だ / ～とは', 5, 6, TRUE, 1),
(543, 109, 'Bài 20.1 - ～てやまない', '～てやまない', 'Không ngừng, Rất, luôn', 'Là cách nói cứng nhắc. Dùng để diễn tả cảm xúc của người nói luôn mang trong mình 1 tình cảm nào đó rất mạnh. Chú ý : Giới hạn đi với những động từ biểu thị trạng thái của cảm xúc như 願う、期 待する、愛するなど。 Không sử dụng với động từ biểu lộ cảm xúc nhất thời như 失望す る、腹を立てるなど. Chủ ngữ thường là ngôi số 1 nhưng thường bị ẩn đi trong câu văn.', '～てやまない', 5, 1, TRUE, 1),
(544, 109, 'Bài 20.2 - ～に堪えない', '～に堪えない', 'Cảm kích không nói nên lời', 'Là cách nói cứng nhắc dùng để diễn tả cảm xúc của bản thân mạnh đến mức không thể đè nén lại được. Chú ý : Chỉ đi với những danh từ giới hạn biểu thị cảm xúc như 感謝、感激、同情な ど。Chủ ngữ thường là ngôi số 1 và hay được lược bỏ trong câu văn.', '～に堪えない', 5, 2, TRUE, 1),
(545, 109, 'Bài 20.3 - ～ではすまない', '～ではすまない', 'Chỉ còn cách, nhất định sẽ phải…', 'する ＝ せず Dùng để nói khi hễ cứ nghĩ đến hoàn cảnh đó hay nghĩ đến quy tắc thông thường trong xã hội thì bản thân không thể không làm. Chú ý : Khó có thể sử dụng với trường hợp liên tưởng từ cảm xúc của bản thân mình mà phải làm như vậy.', '～ではすまない', 5, 3, TRUE, 1),
(546, 109, 'Bài 20.4 - ～ないではおかない', '～ないではおかない', 'Theo lẽ tự nhiên thì', 'する ＝ せず Dùng để nói lên sự khẳng định của người nói chắc chắn 1 việc sẽ xảy ra 1 cách tự nhiên. Chú ý : Trong câu văn thể hiện quyết tâm cao thì chủ ngữ là ngôi thứ 1. Với những câu văn thể hiện sự khẳng định chắc chắn 1 việc nào đó sẽ hình thành thì chủ ngữ không dùng cho ngôi số 1 và vật vô tri vô giác.', '～ないではおかない', 5, 4, TRUE, 1),
(547, 109, 'Bài 20.5 - ～を禁じ得ない', '～を禁じ得ない', 'Không ngăn được, không kìm được…', 'Là cách nói cứng nhắc để diễn tả cảm xúc sôi sục của bản thân đến mức không thể kìm nén khi gặp 1 sự việc nào đó. Chú ý : Đi với danh từ bao hàm nghĩa thể hiện cảm xúc. Chủ ngữ thường là ngôi số 1 nhưng thường được ẩn đi trong câu văn. .', '～を禁じ得ない', 5, 5, TRUE, 1),
(548, 109, 'Bài 20.6 - ～を余儀なくされる / ～を余儀なくさせる', '～を余儀なくされる / ～を余儀なくさせる', 'Bị buộc phải', 'Là cách nói cứng nhắc để diễn tả việc mình buộc phải làm, bị thúc ép làm do 1 sự tình nào đó xảy ra . Chú ý : Với を余儀なくされる thì chủ ngữ thường là con người. Với を余儀なくさせる chủ ngữ không dùng cho con người.', '～を余儀なくされる / ～を余儀なくさせる', 5, 6, TRUE, 1)
INSERT INTO grammar_examples (id, grammar_lesson_id, japanese_text, reading, meaning_vi, display_order) VALUES
(575, 452, 'うちの子はいつも学校から帰ってきて、かばんを放り出すが早いか、遊びに行ってしまう。', 'うちのこはいつもがっこうからかえってきて、かばんをほうりだすがはやいか、あそびにいってしまう。', 'Thằng con nhà tôi á, cứ đi học về, vứt cặp xuống một cái là chạy đi chơi luôn', 1),
(576, 453, '帰宅するや、愛犬が飛びついてきた。', 'きたくするや、あいけんがとびついてきた。', 'Tôi vừa về đến nhà là cún yêu đã chồm ra', 1),
(577, 454, '彼は夕飯を食べるなり、寝てしまった。', 'かれはゆうはんをたべるなり、ねてしまった。', 'Anh ta vừa ăn tối xong đã lăn ra ngủ mất', 1),
(578, 455, '毎日返事を書くそばから次々に新しいメールが来る。', 'まいにちへんじをかくそばからつぎつぎにあたらしいめーるがくる。', 'Ngày nào cũng cứ vừa mới viết mail trả lời xong thì liên tục có mail mới gửi đến', 1),
(579, 456, '日本に来てからというもの、国の家族のことを思わない日はない。', 'にっぽんにきてからというもの、くにのかぞくのことをおもわないにちはない。', 'Kể từ khi đến Nhật, không ngày nào là tôi không nghĩ về gia đình', 1),
(580, 457, 'どんなに厳しい状況にあっても、彼は笑顔を絶やさない。', 'どんなにいかめしいじょうきょうにあっても、かれはえがおをたやさない。', 'Dù trong hoàn cảnh khắc nghiệt thế nào đi nữa, anh ấy vẫn luôn tươi cười', 1),
(581, 458, '今度日本出店を皮切りに彼はヨーロッパに進出しようとしている。', 'こんどにっぽんでみせをかわきりりにかれはよーろっぱにしんしゅつしようとしている。', 'Bắt đầu với việc mở cửa hàng tại Nhật lần này, anh ta muốn tiến sang toàn thị trường châu Âu', 1),
(582, 459, '日常おかずから高級料理の食材に至るまで、この店にないものはない。', 'にちじょうおかずからこうきゅうりょうりのしょくざいにいたるまで、このみせにないものはない。', 'Từ những món ăn thường ngày cho đến cả nguyên liệu làm món ăn cao cấp, chẳng có thứ gì mà cửa hàng này lại không có', 1),
(583, 460, 'この高校は今年を限りに生徒を募集しないことになっている。', 'このこうこうはこんねんをかぎりにせいとをぼしゅうしないことになっている。', 'Trường trung học này đến hết năm nay sẽ không tuyển thêm học sinh nữa', 1),
(584, 461, '３月末日をもって、このサービスは停止させていただきます。', '３げつまつじつをもって、このさーびすはていしさせていただきます。', 'Đến hết ngày cuối cùng của tháng 3, chúng tôi xin ngừng cung cấp dịch vụ này', 1),
(585, 462, 'このクラスのテストの平均点は、毎回せいぜい67、8 点といったところです。', 'このくらすのてすとのへいきんてんは、まいかいせいぜい67、8 てんといったところです。', 'Điểm kiểm tra trung bình của lớp này, mỗi lần nhiều nhất cũng chỉ 67, 68 điểm', 1),
(586, 463, '私が将来やりたい仕事は、教師をおいてほかに考えられない。', 'わたしがしょうらいやりたいしごとは、きょうしをおいてほかにかんがえられない。', 'Nói về công việc tôi muốn làm trong tương lai thì ngoài việc dạy học ra, tôi không thể nghĩ đến việc gì khác', 1),
(587, 464, 'こんな素晴らしい字は、林さんならではだ。', 'こんなすばらしいじは、はやしさんならではだ。', 'Chữ đẹp như thế này thì chỉ có thể là của anh Hayashi', 1),
(588, 465, '母のケーキ作りは単なる趣味にとどまらず、自分の店を開くまでになった。', 'ははのけーきつくりはたんなるしゅみにとどまらず、じぶんのみせをひらくまでになった。', 'Việc làm bánh của mẹ tôi không chỉ đơn giản là sở thích bình thường mà mẹ tôi còn mở hẳn cửa hàng bánh của riêng mình', 1),
(589, 466, '手間がかかる料理はおろか、日常の簡単な料理を作るのさえ面倒だ。', 'てまがかかるりょうりはおろか、にちじょうのかんたんなりょうりをつくるのさえめんどうだ。', 'Chưa nói đến các món ăn làm mất nhiều công sức, ngay cả đến việc nấu những món đơn giản hàng ngày tôi cũng thấy phiền phức rồi', 1),
(590, 467, '試合に勝つには選手の実力もさることながら、運も必要なのだ。', 'しあいにかつにはせんしゅのじつりょくもさることながら、うんもひつようなのだ。', 'Việc chiến thắng trong trận đấu thì phải dựa vào thực lực của các cầu thủ nhưng hơn thế nữa, may mắn cũng rất cần thiết', 1),
(591, 468, '電話なりメールなり知らせる方法はあるはずですよ。', 'でんわなりめーるなりしらせるほうほうはあるはずですよ。', 'Gọi điện hay gửi email cũng được, kiểu gì chả có cách thông báo', 1),
(592, 469, 'ビールであろうとワインであろうと、酒は酒だ。運転前に絶対飲んではいけない。', 'びーるであろうとわいんであろうと、さけはさけだ。うんてんまえにぜったいのんではいけない。', 'Bia hay rượu, thì cũng là đồ uống có cồn. Không thể uống trước khi lái xe được', 1),
(593, 470, 'この虫は色といい形といい、木の葉にそっくりだ。', 'このむしはいろといいかたちといい、このはにそっくりだ。', 'Loài côn trùng này cả màu sắc lẫn hình dáng đều giống hệt lá cây', 1),
(594, 471, 'この虫は色といい形といい、木の葉にそっくりだ。', 'このむしはいろといいかたちといい、このはにそっくりだ。', 'Loài côn trùng này cả màu sắc lẫn hình dáng đều giống hệt lá cây', 1),
(595, 472, '父は、体調いかんでは、会社を辞めるかもしれない。', 'ちちは、たいちょういかんでは、かいしゃをやめるかもしれない。', 'Dựa vào tình hình sức khỏe có thể bố tôi sẽ phải nghỉ việc', 1),
(596, 473, '内容のいかんにかかわらず、個人情報の問い合わせにはお答えしておりません。', 'ないようのいかんにかかわらず、こじんじょうほうのといあわせにはおこたえしておりません。', 'Chúng tôi sẽ không trả lời các câu hỏi liên quan đến thông tin cá nhân dù là bất cứ nội dung nào', 1),
(597, 474, '隊員たいいんたちは危険をものともせずに、行方不明ゆくえふめいの人の捜索そうさくを続けた。', 'たいいんたいいんたちはきけんをものともせずに、ゆくえふめいゆくえふめいのにんのそうさくそうさくをつづけた。', 'Nhóm cứu hộ đã không quản ngại nguy hiểm tiếp tục tìm kiếm những người bị mất tích', 1),
(598, 475, '親の心配をよそに、彼は早朝からサーフインに出かけて行った。', 'おやのしんぱいをよそに、かれはそうちょうからさーふいんにでかけていった。', 'Mặc kệ bố mẹ lo lắng, từ sáng sớm anh ta đã ra khỏi nhà đi lướt sóng', 1),
(599, 476, '5 歳の子供ならいざしらず、大人がこんなことを知らないなんておかしい。', '5 としのこどもならいざしらず、おとながこんなことをしらないなんておかしい。', 'Đứa trẻ 5 tuổi thì không nói nhưng người lớn mà không biết điều này thì lạ quá', 1),
(600, 477, '5 歳の子供ならいざしらず、大人がこんなことを知らないなんておかしい。', '5 としのこどもならいざしらず、おとながこんなことをしらないなんておかしい。', 'Đứa trẻ 5 tuổi thì không nói nhưng người lớn mà không biết điều này thì lạ quá', 1),
(601, 478, '子供はもう歩けないとばかりに、その場にしゃがみ込んでしまった。', 'こどもはもうあるけないとばかりに、そのばにしゃがみこんでしまった。', 'Con tôi ngồi bệt xuống chỗ đó như thể muốn nói là “con không thể đi được nữa đâu”', 1),
(602, 479, 'テレビを見るともなく見ていたら、友達がテレビに出ていてびっくりした。', 'てれびをみるともなくみていたら、ともだちがてれびにでていてびっくりした。', 'Đang xem ti vi một cách vô thức thì tự nhiên thấy bạn xuất hiện trên ti vi khiến tôi rất ngạc nhiên', 1),
(603, 480, '祖母は涙ながらに戦争中の思い出話を語った。', 'そぼはなみだながらにせんそうちゅうのおもいでばなしをかたった。', 'Bà tôi vừa khóc vừa kể lại những hồi ức trong chiến tranh', 1),
(604, 481, '弟は頭で考えるだけで行動に移さないきらいがある。', 'おとうとはあたまでかんがえるだけでこうどうにうつさないきらいがある。', 'Em trai tôi hay có kiểu chỉ suy nghĩ trong đầu mà không chịu chuyển thành hành động', 1),
(605, 482, '友達を駅まで送りがてらDVD を返してきた。', 'ともだちをえきまでおくりがてらDVD をかえしてきた。', 'Tiện thể lúc tiễn bạn ra ga tôi mang trả đĩa DVD', 1),
(606, 483, '部長のお宅へお礼かたがたごあいさつに行こうと思っています。', 'ぶちょうのおたくへおれいかたがたごあいさつにいこうとおもっています。', 'Tôi dự định đến nhà sếp vừa để cảm ơn vừa để chào hỏi xã giao luôn', 1),
(607, 484, '母は数学を教えるかたわら翻訳の仕事もしている。', 'はははすうがくをおしえるかたわらほんやくのしごともしている。', 'Ngoài việc chính là dạy toán mẹ tôi còn làm thêm cả việc biên dịch', 1),
(608, 485, 'お忙しいところを手伝ってくださってありがとうございました。', 'おいそがしいところをてつだってくださってありがとうございました。', 'Vào lúc anh đang bận nhưng vẫn giúp đỡ tôi nên tôi rất cảm kích', 1),
(609, 486, 'よせばいいものを、彼は社長に大声で文句を言った。そのため会社を首になった。', 'よせばいいものを、かれはしゃちょうにおおごえでもんくをいった。そのためかいしゃをくびになった。', 'Nếu mà chịu dừng lại thì tốt rồi nhưng anh ta lại to tiếng phàn nàn với giám đốc. Kết quả là anh ta đã bị sa thải', 1),
(610, 487, '有給休暇があるとはいえ、休みはなかなか取れないものだ。', 'ゆうきゅうきゅうかがあるとはいえ、やすみはなかなかとれないものだ。', 'Tuy là có kì nghỉ phép đấy nhưng mãi mà vẫn không xin nghỉ được', 1),
(611, 488, '未成年者といえども、公共の場で勝手なことをしてはならない。', 'みせいねんしゃといえども、こうきょうのばでかってなことをしてはならない。', 'Dù là trẻ vị thành niên đi chăng nữa cũng không được hành động tùy tiện ở nơi công cộng', 1),
(612, 489, '今日は一日中晴れると思いきや、午後からざあざあ降りになった。', 'こんにちはいちにちじゅうはれるとおもいきや、ごごからざあざあおりになった。', 'Cứ nghĩ là cả ngày trời sẽ nắng nhưng đến chiều thì đã mưa rào rào', 1),
(613, 490, 'あなたの頼みとあれば、精いっぱい頑張ります。', 'あなたのたのみとあれば、せいいっぱいがんばります。', 'Nếu mà em đã nhờ vả thì anh sẽ cố gắng hết sức', 1),
(614, 491, '兄は大酒（おおざけ）飲みだから、飲み始めたら最後酔いつぶれるまで飲んでしまう。', 'あにはおおざけ（おおざけ）のみだから、のみはじめたらさいごよいつぶれるまでのんでしまう。', 'Anh trai tôi uống rượu nhiều nên nếu đã bắt đầu uống thì thế nào cũng uống đến không biết trời đất là gì', 1),
(615, 492, '敬語がちゃんと使えないようでは、接客（せっきゃく）の仕事はできない。', 'けいごがちゃんとつかえないようでは、せっきゃく（せっきゃく）のしごとはできない。', 'Nếu mà không dùng chuẩn được kính ngữ thì không làm được công việc giao tiếp với khách hàng đâu', 1),
(616, 493, '十分な話し合いなくしてはダムの建設の問題は解決しないだろう。', 'じゅうぶんなはなしあいなくしてはだむのけんせつのもんだいはかいけつしないだろう。', 'Nếu không có sự thảo luận giữa các bên thì vấn đề liên quan đến việc xây đập chắc là khó giải quyết được', 1),
(617, 494, '結婚して自由がなくなるくらいなら、一人で暮らすほうがましだ。', 'けっこんしてじゆうがなくなるくらいなら、ひとりでくらすほうがましだ。', 'Thà sống một mình còn hơn kết hôn xong lại mất tự do', 1),
(618, 495, 'いかに困難だろうと、戦争のない世界を目指して闘いたい。', 'いかにこんなんだろうと、せんそうのないせかいをめざしてたたかいたい。', 'Dù có khó khăn bao nhiêu đi nữa chúng tôi vẫn muốn đấu tranh vì một thế giới không có chiến tranh', 1),
(619, 496, '私が明日の会に参加しようとするまいと、あなたには関係ないことでしょう。', 'わたしがあしたのかいにさんかしようとするまいと、あなたにはかんけいないことでしょう。', 'Tớ có tham gia hội ngày mai hay không thì có liên quan gì đến cậu đâu nhỉ', 1),
(620, 497, '理由が何であれ、無断 (むだん) 欠席は許さない。', 'りゆうがなんであれ、むだん (むだん) けっせきはゆるさない。', 'Dù lí do là gì đi nữa thì việc vắng mặt không phép là không thể chấp nhận được', 1),
(621, 498, 'そのまま考え続けたところで、これ以上いいアイディアは出てこないだろう。', 'そのままかんがえつづけたところで、これいじょういいあいでぃあはでてこないだろう。', 'Cứ tiếp tục nghĩ như thế này nữa thì cũng không ra được ý tưởng nào tốt hơn đâu', 1),
(622, 499, '引っ越しの前も大変だったが、引っ越したら引っ越したで、またやらなければならないことがたくさんある。', 'ひっこしのまえもたいへんだったが、ひっこしたらひっこしたで、またやらなければならないことがたくさんある。', 'Trước khi chuyển nhà đã mệt rồi, đến lúc chuyển xong thì lại có lắm việc phải làm', 1),
(623, 500, '介護ロボットを開発すべく、私達は今日も実験を続ける。', 'かいごろぼっとをかいはつすべく、わたしたちはきょうもじっけんをつづける。', 'Chúng tôi ngày nào cũng tiến hành thí nghiệm để phát triển robot điều dưỡng', 1),
(624, 501, '彼女は歌手になりたいという夢を実現(じつげん)させんがため、上京 (じょうきょう)した。', 'かのじょはかしゅになりたいというゆめをじつげん(じつげん)させんがため、じょうきょう (じょうきょう)した。', 'Cô ấy đã lên Tokyo để thực hiện ước mơ trở thành ca sỹ', 1),
(625, 502, '最新の医療技術をもってすれば、人はさらに寿命に延ばせるだろう。', 'さいしんのいりょうぎじゅつをもってすれば、にんはさらにじゅみょうにのばせるだろう。', 'Với kĩ thuật y học tiên tiến nhất thì khả năng sẽ kéo dài được tuổi thọ của con người', 1),
(626, 503, '愛していればこそ、別れるのです。私の気持ち、分かってください。', 'いとしていればこそ、わかれるのです。わたしのきもち、わかってください。', 'Chính vì yêu anh, nên em mới phải chia tay. Xin anh hãy hiểu cho em', 1),
(627, 504, '梅雨の晴れ間とあって、どの家も洗濯物を干している。', 'つゆのはれまとあって、どのいえもせんたくものをほしている。', 'Vì gặp ngày nắng trong mùa mưa nên nhà nào cũng phơi quần áo', 1),
(628, 505, 'あなたが悪かったわけではあるまいし、そんなに自分を責せめることはないよ。', 'あなたがわるかったわけではあるまいし、そんなにじぶんをせきせめることはないよ。', 'Cũng chẳng phải là do cậu không tốt nên đừng cứ đổ lỗi cho bản thân như thế nữa', 1),
(629, 506, 'いつも手伝ってもらっている手前、今回はこちらから手伝いを申(もう)し出(で)ないければ・・・', 'いつもてつだってもらっているてまえ、こんかいはこちらからてつだいをさる(もう)ししゅつ(で)ないければ・・・', 'Vì lúc nào anh cũng giúp đỡ tôi nên lần này hãy để tôi giúp anh', 1),
(630, 507, '慣れないことゆえ、数々の不手際、どうぞお許してください。', 'なれないことゆえ、かずかずのふてぎわ、どうぞおゆるしてください。', 'Vì chưa quen nên tôi còn lóng ngóng vụng về, xin vui lòng bỏ qua cho tôi', 1),
(631, 508, '愛する人を失った彼女の悲しみは察するにかかたくない。', 'あいするにんをうったかのじょのかなしみはさっするにかかたくない。', 'Có thể hiểu được cô ấy đã đau buồn thế nào khi mất đi người thân yêu', 1),
(632, 509, 'こどもに大切な書類を汚され、泣くに泣けない心境だ。', 'こどもにたいせつなしょるいをよごされ、なくになけないしんきょうだ。', 'Bị con làm bẩn mất tài liệu quan trọng, tôi muốn khóc mà không khóc nổi', 1),
(633, 510, '発(しゅっぱつ)の時間を20 分も過ぎた。遅い人もうこれ以上待ってはいられない。', 'はつ(しゅっぱつ)のじかんを20 ふんもすぎた。おそいにんもうこれいじょうまってはいられない。', 'Đã quá giờ xuất phát 20 phút rồi. Không thể tiếp tục đợi những người đến muộn nữa', 1),
(634, 511, 'この絵が偽物であることなど、素人の私は知るべくもない。', 'このえがにせものであることなど、しろうとのわたしはしるべくもない。', 'Một người nghiệp dư như tôi thì làm sao mà biết được đay là bức tranh giả', 1),
(635, 512, '現代の社会にはパソコンは欠くべからざる存在となっている。', 'げんだいのしゃかいにはぱそこんはかくべからざるそんざいとなっている。', 'Trong xã hội hiện đại , máy tính cá nhân đã trở thành thứ không thể thiếu', 1),
(636, 513, '弱い者いじめをするなど、許すまじきことです。', 'よわいものいじめをするなど、ゆるすまじきことです。', 'Bắt nạt những người yếu đuối hơn mình là một hành động khó tha thứ được', 1),
(637, 514, '8. うちの息子ときなら、休みになると部屋にこもってテレビゲームばかりする。', '8. うちのむすこときなら、やすみになるとへやにこもっててれびげーむばかりする。', 'Nói về thằng con nhà tôi thì cứ được nghỉ là nó lại rúc trong phòng chơi game', 1),
(638, 515, '社会人ともなると、服装や言葉遣いにも気をつけなければならない。', 'しゃかいじんともなると、ふくそうやことばづかいにもきをつけなければならない。', 'Nếu là người đi làm thì phải chú ý đến trang phục và lời ăn tiếng nói', 1),
(639, 516, '愛する人を失った彼女の悲しみは察するにかかたくない。', 'あいするにんをうったかのじょのかなしみはさっするにかかたくない。', 'Có thể hiểu được cô ấy đã đau buồn thế nào khi mất đi người thân yêu', 1),
(640, 517, '警察官寮ともあろう者が、賄賂を受け取るとは驚いた。', 'けいさつかんりょうともあろうものが、わいろをうけとるとはおどろいた。', 'Không thể ngờ được là một cảnh sát viên mà lại đi ăn cướp', 1),
(641, 518, '彼は経験が浅いなりに、一生懸命仕事をしている。', 'かれはけいけんがあさいなりに、いっしょうけんめいしごとをしている。', 'Anh ấy vì là còn thiếu kinh nghiệm nên là làm việc chăm chỉ', 1),
(642, 519, '前日までのひどい天気にひきかえ、運動会の当日は気持ちよく晴れて良かった。', 'ぜんじつまでのひどいてんきにひきかえ、うんどうかいのとうじつはきもちよくはれてよかった。', 'So với thời tiết tệ hại cho đến ngày hôm trước đó, hôm diễn ra hội thao thời tiết ấm áp và dễ chịu hơn nhiều. N', 1),
(643, 520, '結婚式の日の彼女は、いつにもまして美しかった。', 'けっこんしきのにちのかのじょは、いつにもましてうつくしかった。', 'Vào ngày hôn lễ, cô gái tôi yêu trông xinh đẹp hơn bất cứ lúc nào', 1),
(644, 521, 'わたしたち夫婦は海外旅行などのぜいたくはできないまでも、不自由のない暮らしをしています。', 'わたしたちふうふはかいがいりょこうなどのぜいたくはできないまでも、ふじゆうのないくらしをしています。', 'Vợ chồng chúng tôi dù chẳng có tiền để đi du lịch nước ngoài nhưng vẫn có một cuộc sống đầy đủ không thiếu thốn gì', 1),
(645, 522, '死者が出るに至って、国は初めて病気の感染拡大の深刻さに気がついたのだ。', 'ししゃがでるにいたって、くにははじめてびょうきのかんせんかくだいのしんこくさにきがついたのだ。', 'Phải đến tận khi có người tử vong, quốc gia mới bắt đầu cảm nhận được tính nghiêm trọng của sự lây nhiễm lan rộng của căn bệnh này', 1),
(646, 523, '毎年この地方は洪水の被害を受ける。長崎県に至っては今年もう３回目だ。', 'まいとしこのちほうはこうずいのひがいをうける。ながさきけんにいたってはこんねんもう３かいめだ。', 'Vùng này năm nào cũng phải chịu thiệt hại từ lũ lụt, riêng Nagasaki thì năm nay đã là lần thứ 3 rồi đấy', 1),
(647, 524, 'ゴルフを始めたが、腰を痛めてしまい、病院に通う始末だ。', 'ごるふをはじめたが、こしをいためてしまい、びょういんにかようしまつだ。', 'Tôi mới bắt đầu chơi gôn nhưng bị đau lưng, kết cục là phải đến bệnh viện', 1),
(648, 525, '講演会では休憩もなしに２時間も話しっぱなしで、とても疲れた。', 'こうえんかいではきゅうけいもなしに２じかんもはなしっぱなしで、とてもつかれた。', 'Trong buổi diễn thuyết vì tôi phải nói suốt 2 tiếng không nghỉ nên rất mệt', 1),
(649, 526, 'あなたのことは１日たりとも忘れたことはありません。', 'あなたのことは１にちたりともわすれたことはありません。', 'Anh chưa bao giờ quên em dù chỉ một ngày', 1),
(650, 527, '大学の教授ですら、その問題には答えられなかった。', 'だいがくのきょうじゅですら、そのもんだいにはこたえられなかった。', 'Ngay cả giáo sư đại học cũng không thể trả lời được câu hỏi đó', 1),
(651, 528, 'こんなことになると、夢にだに思わなかった。', 'こんなことになると、ゆめにだにおもわなかった。', 'Ngay cả trong giấc mơ tôi cũng không nghĩ sự việc sẽ trở nên như thế này', 1),
(652, 529, '彼は４０歳にしてようやく自分の生きるべき道を見つけた。', 'かれは４０としにしてようやくじぶんのいきるべきみちをみつけた。', 'Anh ta mãi đến khoảng 40 tuổi mới tìm thấy con đường mình nên đi', 1),
(653, 530, 'どんなに有名でも、お客様あってのお店です。', 'どんなにゆうめいでも、おきゃくさまあってのおみせです。', 'Dù có nổi tiếng đến đâu thì cửa hàng tồn tại được cần phải có khách hàng', 1),
(654, 531, '身長2 メートルからある男が、突然私の目の前に現れた。', 'しんちょう2 めーとるからあるおとこが、とつぜんわたしのめのまえにあらわれた。', 'Một người đàn ông cao tầm 2 mét bắt ngờ xuất hiện trước mặt tôi', 1),
(655, 532, '予約したホテルは駅を降りたら探すまでもなく目の前にあった。', 'よやくしたほてるはえきをおりたらさがすまでもなくめのまえにあった。', 'Chỗ khách sạn mà tôi đã đặt trước ấy thì ra khỏi ga là thấy luôn, không cần phải đi tìm đâu xa', 1),
(656, 533, 'だれも協力してくれないのなら、一人でやってみるまでだ。', 'だれもきょうりょくしてくれないのなら、ひとりでやってみるまでだ。', 'Vì không được ai hợp tác cùng nên tôi đành làm một mình vậy', 1),
(657, 534, 'いくらお金をためても、死んでしまえばそれまでだ。', 'いくらおきんをためても、しんでしまえばそれまでだ。', 'Dù có để dành bao nhiêu tiền đi nữa thì khi chết là hết', 1),
(658, 535, '彼女の発言は責めるには当たらないと思う。', 'かのじょのはつげんはせめるにはあたらないとおもう。', 'Tôi nghĩ những lời phát biểu của cô ta không đáng để bị chỉ trích', 1),
(659, 536, '毎日仕事が楽しくてしかたがない。これこそ天職でなくてなんだろう。', 'まいにちしごとがたのしくてしかたがない。これこそてんしょくでなくてなんだろう。', 'Công việc hàng ngày thì rất là vui . Tôi không thể tượng tượng được đây chính là công việc trời ban', 1),
(660, 537, '彼は信用して大事を託するに足る男だ。', 'かれはしんようしてだいじをたくするにたるおとこだ。', 'Anh ta là người đáng để tin tưởng và giao những việc lớn', 1),
(661, 538, 'あの人の話はいつも人の悪口ばかりで、聞くに堪えない。', 'あのにんのはなしはいつもにんのわるくちばかりで、きくにこたえない。', 'Người đó luôn nói xấu người khác nên nghe không chịu được', 1),
(662, 539, '彼女が結婚を承諾したときの彼の喜びといったらなかった。', 'かのじょがけっこんをしょうだくしたときのかのよろこびといったらなかった。', 'Anh ấy cực kỳ vui sướng khi cô ấy đồng ý kết hôn', 1),
(663, 540, '自分の作品がこんなに大勢の人に評価されるとは、本当にうれしいかぎりだ。', 'じぶんのさくひんがこんなにおおぜいのにんにひょうかされるとは、ほんとうにうれしいかぎりだ。', 'Tôi rất hạnh phúc vì có được nhiều người đánh giá tác phẩm của mình', 1),
(664, 541, '飲酒運転は危険極まりないです。', 'いんしゅうんてんはきけんきわまりないです。', 'Lái xe sau khi đã uống rượu là vô cùng nguy hiểm', 1),
(665, 542, '外国での一人暮らしがこんなに大変とは思ってみなかったよ。', 'がいこくでのひとりぐらしがこんなにたいへんとはおもってみなかったよ。', 'Tôi đã không tưởng tượng được rằng sống 1 mình ở nước ngoài lại vất vả đến vậy', 1),
(666, 543, 'この写真に写っているのはわたしが愛してやまないふるさとの風景だ。', 'このしゃしんにうつっているのはわたしがいとしてやまないふるさとのふうけいだ。', 'Tôi đã chụp lại trong bức ảnh phong cảnh quê hương mà tôi luôn thương yêu', 1),
(667, 544, 'お忙しいところを多くの方にお集まりいただき、感激に堪えません。', 'おいそがしいところをおおくのほうにおあつまりいただき、かんげきにこたえません。', 'Nhiều người tụ trung lại vào lúc bận rộn thế này, tôi không khỏi cảm thấy xúc động', 1),
(668, 545, '人の心を傷つけてしまったなら、謝らないですまない。', 'にんのこころをきずつけてしまったなら、あやまらないですまない。', 'Nếu làm tổn thương một người nào đó thì nhất định phải xin lỗi họ', 1),
(669, 546, '今度こそ、本当のことを言わせないではおかないぞ。', 'こんどこそ、ほんとうのことをいわせないではおかないぞ。', 'Lần này tôi nhất định phải nói ra sự thật', 1),
(670, 547, '彼女の悲しい話を聞いて、私は涙を禁じえなかった。', 'かのじょのかなしいはなしをきいて、わたしはなみだをきんじえなかった。', 'Khi nghe câu chuyện buồn của cô ấy , tôi đã không thể nào kìm được nước mắt', 1),
(671, 548, '登山の計画は雷雨が発生したため、辞職を余儀なくされた。', 'とざんのけいかくはらいうがはっせいしたため、じしょくをよぎなくされた。', 'Kế hoạch leo núi đã buộc phải dừng lại do trời mưa bão', 1)
