SET NAMES utf8mb4;

DELETE ge FROM grammar_examples ge JOIN grammar_lessons gl ON gl.id = ge.grammar_lesson_id WHERE gl.jlpt_level_id = 5;

DELETE FROM grammar_lessons WHERE jlpt_level_id = 5;

DELETE FROM grammar_chapters WHERE jlpt_level_id = 5;

ON DUPLICATE KEY UPDATE
    jlpt_level_id = VALUES(jlpt_level_id),
    chapter_number = VALUES(chapter_number),
    name = VALUES(name),
    description = VALUES(description),
    display_order = VALUES(display_order),
    is_published = VALUES(is_published),
    version = VALUES(version);

ON DUPLICATE KEY UPDATE
    grammar_chapter_id = VALUES(grammar_chapter_id),
    title = VALUES(title),
    pattern = VALUES(pattern),
    meaning_vi = VALUES(meaning_vi),
    explanation = VALUES(explanation),
    formation = VALUES(formation),
    jlpt_level_id = VALUES(jlpt_level_id),
    display_order = VALUES(display_order),
    is_published = VALUES(is_published),
    version = VALUES(version);

ON DUPLICATE KEY UPDATE
    grammar_lesson_id = VALUES(grammar_lesson_id),
    japanese_text = VALUES(japanese_text),
    reading = VALUES(reading),
    meaning_vi = VALUES(meaning_vi),
    display_order = VALUES(display_order);
